// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategory/** * NOUS — Airplane Mode Handler (Module 10 v2 — Step 10.5). * * Toggles airplane mode on/off. The most restricted of the connectivity * handlers — programmatic toggle requires `WRITE_SECURE_SETTINGS`, granted * only to system apps, rooted devices, or via ADB. * * ## Behavior (per strategy §"Privacy & Security") * *  - **Direct toggle** (system app / rooted / ADB-granted): *    `Settings.Global.AIRPLANE_MODE_ON` write + broadcast *    `Intent.ACTION_AIRPLANE_MODE_CHANGED` so the system updates the radio *    state immediately. * *  - **Fallback** (regular Play Store install): open *    `Settings.ACTION_AIRPLANE_MODE_SETTINGS` page for the user to toggle *    manually. This is the only option on non-rooted, non-system-app devices. * * ## Why is airplane mode so restricted? * * Airplane mode disables **all radios** (cellular, Wi-Fi, Bluetooth, NFC). * Allowing any app to toggle it silently would be a security risk (could * block emergency calls, prevent 911 dialing). Google restricts it to * system apps with `WRITE_SECURE_SETTINGS`. * * ## Idempotent execution (Review 2 Elite 1) * * If airplane mode is already in the target state, skip the toggle (avoids * redundant Settings page opens). * * ## Pre-state capture (Review 2 Fix A) * * Captures the previous on/off state. Undo restores the actual previous * state (or opens Settings page on non-rooted devices). * * ## Resource category * * Airplane mode uses [ResourceCategory.CONNECTIVITY] — toggling it affects * Wi-Fi + Bluetooth + cellular, so it's sequenced with other connectivity * ops. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Privacy & Security — Airplane Mode</a> */class AirplaneModeHandler(    private val airplaneModeService: AirplaneModeService,) : ReversibleHandler<SystemOperation.SetAirplaneMode> {    override val id: String = "airplane_mode"    override val displayName: String = "Airplane Mode Control"    override val requiredPermissions: Set<String> = emptySet()  // WRITE_SECURE_SETTINGS checked at runtime    override val resourceCategory: ResourceCategory = ResourceCategory.CONNECTIVITY    override fun isAvailable(): Boolean = true  // all devices support airplane mode    override suspend fun execute(operation: SystemOperation.SetAirplaneMode): Result<Unit> {        return try {            if (airplaneModeService.canToggleDirectly()) {                // System app / rooted / ADB — direct toggle.                val success = airplaneModeService.setOn(operation.on)                if (success) {                    Result.Success(Unit, CorrelationId.generate(), 0)                } else {                    Result.Failure(                        error = AppError.Hardware.Unknown("airplane_mode"),                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                    )                }            } else {                // Regular app — open Settings page.                val launched = airplaneModeService.openSettingsPage()                if (launched) {                    Result.Success(                        data = Unit,                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                        warnings = listOf("opened_settings_page"),                    )                } else {                    Result.Failure(                        error = AppError.Hardware.Unsupported("airplane_mode_settings"),                        correlationId = CorrelationId.generate(),                        durationNanos = 0,                    )                }            }        } catch (t: Throwable) {            Timber.tag("AirplaneModeHandler").w("execute failed", t)            Result.Failure(                error = AppError.Hardware.Unknown("airplane_mode", t),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }    override suspend fun capturePreState(operation: SystemOperation.SetAirplaneMode): Any? {        return try {            AirplaneModePreState(wasOn = airplaneModeService.isOn())        } catch (t: Throwable) {            Timber.tag("AirplaneModeHandler").w("capturePreState failed", t)            null        }    }    override suspend fun restorePreState(operation: SystemOperation.SetAirplaneMode, preState: Any?) {        if (preState !is AirplaneModePreState) return        try {            if (airplaneModeService.canToggleDirectly()) {                airplaneModeService.setOn(preState.wasOn)            } else {                Timber.tag("AirplaneModeHandler").i("Undo: airplane mode was ${if (preState.wasOn) "on" else "off"} — opening settings for manual restore.")                airplaneModeService.openSettingsPage()            }        } catch (t: Throwable) {            Timber.tag("AirplaneModeHandler").w("restorePreState failed", t)        }    }    override suspend fun getCurrentState(): Any? = try {        AirplaneModePreState(wasOn = airplaneModeService.isOn())    } catch (t: Throwable) { null }    override suspend fun isAlreadyInTargetState(operation: SystemOperation.SetAirplaneMode): Boolean {        return try {            airplaneModeService.isOn() == operation.on        } catch (t: Throwable) {            false        }    }    override fun describeOperation(operation: SystemOperation.SetAirplaneMode): String =        if (operation.on) "Airplane mode turned on" else "Airplane mode turned off"    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is AirplaneModePreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"AirplaneModePreState\",\"wasOn\":${preState.wasOn}}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "AirplaneModePreState" -> AirplaneModePreState(wasOn = (map["wasOn"] as? Boolean) ?: false)            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for airplane mode (previous on/off). */    data class AirplaneModePreState(val wasOn: Boolean)}
